function draw(ctx, state, t) {
  var top = 36;
  var bot = 286;
  var thr = 0;
  var x = state.x;
  var xmin = -4;
  var xmax = 3;
  var ymin = -0.6;
  var ymax = 3.2;
  function fmt(v) { return Math.round(v * 100) / 100; }
  function erf(v) {
    var neg = false;
    var ax = v;
    if (ax < 0) { neg = true; ax = 0 - ax; }
    var tt = 1 / (1 + 0.33 * ax);
    var t2 = tt * tt;
    var t3 = t2 * tt;
    var t4 = t3 * tt;
    var t5 = t4 * tt;
    var y = 1 - (0.25 * tt - 0.28 * t2 + 1.42 * t3 - 1.45 * t4 + 1.06 * t5) * Math.exp(0 - ax * ax);
    if (neg) { y = 0 - y; }
    return y;
  }
  function Phi(v) { return 0.5 * (1 + erf(v / Math.sqrt(2))); }
  function gelu(v) { return v * Phi(v); }
  function XtoPx(v) { return 48 + (v - xmin) / (xmax - xmin) * (560 - 48); }
  function YtoPy(v) { return bot - (v - ymin) / (ymax - ymin) * (bot - top); }
  var ythr = YtoPy(thr);
  var i = 0;
  var n = 120;
  var xv = 0;
  var yv = 0;
  var px = 0;
  var py = 0;
  var clip = false;
  ctx.clearRect(0, 0, state.w, state.h);
  ctx.fillStyle = "#f6f3ec";
  ctx.fillRect(0, 0, state.w, state.h);
  ctx.strokeStyle = "#1f4b99";
  ctx.lineWidth = 2;
  ctx.beginPath();
  for (i = 0; i <= n; i++) {
    xv = xmin + (xmax - xmin) * i / n;
    yv = gelu(xv);
    px = XtoPx(xv);
    py = YtoPy(yv);
    if (py < 36 || py > 286) { clip = true; }
    if (i === 0) { ctx.moveTo(px, py); } else { ctx.lineTo(px, py); }
  }
  ctx.stroke();
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(48, ythr);
  ctx.lineTo(560, ythr);
  ctx.stroke();
  yv = gelu(x);
  px = XtoPx(x);
  py = YtoPy(yv);
  ctx.beginPath();
  ctx.moveTo(px, ythr);
  ctx.lineTo(px, py);
  ctx.stroke();
  ctx.fillStyle = "#c4512c";
  ctx.beginPath();
  ctx.arc(px, py, 5, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = "#1f4b99";
  ctx.font = "12px sans-serif";
  ctx.fillText("threshold " + fmt(thr), 48, ythr - 8);
  ctx.fillText("x = " + fmt(x), 48, 318);
  ctx.fillText("y = " + fmt(yv), 300, 318);
  if (clip) { ctx.fillText("clipped", 460, 318); }
  ctx.fillText("toy arXiv 1606.08415 only holds if smooth", 48, 344);
}
